static char g_t[160];

static wf_cssview_t view(long long start, long long size, long long vw, long long range, long long pos, int k0,
                         int v0, int k1, int v1) {
    wf_cssview_t v;
    memset(&v, 0x5a, sizeof(v));
    v.start = start; v.size = size; v.view = vw; v.range = range; v.pos = pos;
    v.ik[0] = (unsigned char)k0; v.iv[0] = v0; v.ik[1] = (unsigned char)k1; v.iv[1] = v1;
    return v;
}

static const char *vr(long long start, long long size, long long vw, long long range, long long pos, int k0,
                      int v0, int k1, int v1, int r) {
    wf_cssview_t v = view(start, size, vw, range, pos, k0, v0, k1, v1);
    long long lo = -7, hi = -7;
    if (!wf_cssview_range(&v, r, &lo, &hi)) return lo == -7 && hi == -7 ? "0" : "WRITTEN";
    snprintf(g_t, sizeof(g_t), "1 %lld %lld", lo, hi);
    return g_t;
}

static const char *ve(long long start, long long size, long long vw, long long range, long long pos, int k0,
                      int v0, int k1, int v1, int kind, int val, int len, int end) {
    wf_cssview_t v = view(start, size, vw, range, pos, k0, v0, k1, v1);
    long long out = -7;
    int r = wf_cssview_edge(&v, kind, val, len, end, &out);
    snprintf(g_t, sizeof(g_t), "%d %lld", r, out);
    return g_t;
}

static void anim(wf_cssanim_t *a, int dur, int delay, int iters, int rsk, int rsp, int rsl, int rek, int rep,
                 int rel) {
    memset(a, 0, sizeof(*a));
    a->dur = dur; a->delay = delay; a->iters = iters;
    a->rs = (unsigned char)rsk; a->rsp = rsp; a->rsl = (unsigned char)rsl;
    a->re = (unsigned char)rek; a->rep = rep; a->rel = (unsigned char)rel;
}

static const char *vm(int dur, int delay, int iters, int rsk, int rsp, int rsl, int rek, int rep, int rel,
                      long long start, long long size, long long vw, long long range, long long pos, int k0,
                      int v0, int k1, int v1) {
    wf_cssanim_t a;
    wf_cssview_t v = view(start, size, vw, range, pos, k0, v0, k1, v1);
    int ms = -7, r;
    anim(&a, dur, delay, iters, rsk, rsp, rsl, rek, rep, rel);
    r = wf_cssanim_view_ms(&a, &v, &ms);
    snprintf(g_t, sizeof(g_t), "%d %d", r, ms);
    return g_t;
}

static const char *spx(int dur, int delay, int iters, int rsk, int rsp, int rsl, int rek, int rep, int rel,
                       long long range, long long pos) {
    wf_cssanim_t a, b;
    int ms = -7, r;
    anim(&a, dur, delay, iters, rsk, rsp, rsl, rek, rep, rel);
    b = a;
    r = wf_cssanim_scroll_px_ms(&a, range, pos, &ms);
    if (memcmp(&a, &b, sizeof(a))) return "CHANGED";
    snprintf(g_t, sizeof(g_t), "%d %d", r, ms);
    return g_t;
}

